<?php
declare(strict_types=1);require_once __DIR__.'/functions.php';require_login();$uid=current_user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);if(($_POST['action']??'')==='toggle'&&$id>0){$q=db()->prepare('UPDATE notifications SET is_read = NOT is_read WHERE id = ? AND user_id = ?');$q->execute([$id,$uid]);}elseif(($_POST['action']??'')==='read_all'){$q=db()->prepare('UPDATE notifications SET is_read = 1 WHERE user_id = ?');$q->execute([$uid]);}header('Location: notifications.php');exit;}$q=db()->prepare('SELECT id,message,is_read,created_at FROM notifications WHERE user_id = ? ORDER BY created_at DESC LIMIT 100');$q->execute([$uid]);$items=$q->fetchAll();$unread=count(array_filter($items,fn($n)=>(int)$n['is_read']===0));page_start('Notifications','notifications.php');
?><div class="page-heading"><div><p class="overline">STAY IN THE LOOP</p><h1>Notifications</h1><p class="heading-subtitle">Updates and reminders from your AttendEase workspace.</p></div><?php if($unread):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="read_all"><button class="btn btn-outline-secondary mark-all">Mark all as read</button></form><?php endif?></div><section class="content-card notifications-card"><div class="card-heading"><div><h2>Your updates <span class="count-bubble"><?=count($items)?></span></h2><p><?=number_format($unread)?> unread <?=($unread===1?'notification':'notifications')?></p></div><span class="notification-bell">♧</span></div><div class="notification-list"><?php if(!$items):?><div class="notification-empty"><span>♧</span><strong>You’re all caught up</strong><p>New announcements and reminders will show up here.</p></div><?php else:foreach($items as $item):?><article class="notification-item <?=$item['is_read']?'is-read':'is-unread'?>"><div class="notification-symbol <?=((int)$item['is_read'])?'symbol-muted':'symbol-blue'?>"><?=((int)$item['is_read'])?'✓':'✦'?></div><div class="notification-copy"><p><?=nl2br(e($item['message']))?></p><span><?=e(date('M j, Y · g:i A',strtotime($item['created_at'])))?></span></div><div class="notification-actions"><?php if(!$item['is_read']):?><span class="unread-dot" title="Unread"></span><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=e($item['id'])?>"><button class="notification-toggle" title="<?=$item['is_read']?'Mark unread':'Mark read'?>" aria-label="<?=$item['is_read']?'Mark unread':'Mark read'?>"><?=$item['is_read']?'↶':'✓'?></button></form></div></article><?php endforeach;endif?></div></section><?php page_end();
